package com.medipulse.backend.controller;
import com.medipulse.backend.dto.*;import com.medipulse.backend.entity.User;import com.medipulse.backend.exception.UnauthorizedException;import com.medipulse.backend.service.*;import jakarta.servlet.http.HttpServletRequest;import jakarta.validation.Valid;import org.springframework.http.HttpStatus;import org.springframework.http.ResponseEntity;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/auth") public class AuthController{
    private final UserService userService;private final JwtService jwtService;private final LoginRateLimiter rateLimiter;
    public AuthController(UserService userService,JwtService jwtService,LoginRateLimiter rateLimiter){this.userService=userService;this.jwtService=jwtService;this.rateLimiter=rateLimiter;}
    @PostMapping("/register") public ResponseEntity<UserResponse> register(@Valid @RequestBody RegisterRequest request){return ResponseEntity.status(HttpStatus.CREATED).body(new UserResponse(userService.createUser(request)));}
    @PostMapping("/login") public ResponseEntity<LoginResponse> login(@Valid @RequestBody LoginRequest request,HttpServletRequest servletRequest){String key=(servletRequest.getRemoteAddr()==null?"unknown":servletRequest.getRemoteAddr())+":"+request.getEmail().trim().toLowerCase();if(rateLimiter.isBlocked(key))throw new UnauthorizedException("Too many failed login attempts. Please try again in 5 minutes.");User user=userService.login(request.getEmail(),request.getPassword()).orElse(null);if(user==null){rateLimiter.recordFailure(key);throw new UnauthorizedException("Invalid email or password");}rateLimiter.clear(key);return ResponseEntity.ok(issue(user));}
    @PostMapping("/forgot-password/question") public ResponseEntity<java.util.Map<String,String>> forgotPasswordQuestion(@Valid @RequestBody ForgotPasswordQuestionRequest request){String question=userService.getSecurityQuestion(request.getEmail());return ResponseEntity.ok(java.util.Map.of("question",question));}
    @PostMapping("/forgot-password/reset") public ResponseEntity<Void> resetPassword(@Valid @RequestBody ResetPasswordRequest request,HttpServletRequest servletRequest){String key=(servletRequest.getRemoteAddr()==null?"unknown":servletRequest.getRemoteAddr())+":reset:"+request.getEmail().trim().toLowerCase();if(rateLimiter.isBlocked(key))throw new UnauthorizedException("Too many reset attempts. Please try again in 5 minutes.");try{userService.resetPasswordWithSecurityAnswer(request.getEmail(),request.getSecurityAnswer(),request.getNewPassword());}catch(UnauthorizedException e){rateLimiter.recordFailure(key);throw e;}rateLimiter.clear(key);return ResponseEntity.noContent().build();}
    @PostMapping("/refresh") public ResponseEntity<LoginResponse> refresh(@RequestParam String refreshToken){try{if(!"refresh".equals(jwtService.extractType(refreshToken)))throw new UnauthorizedException("Invalid refresh token");Long userId=jwtService.extractUserId(refreshToken);User user=userService.getUserById(userId).filter(User::isActive).orElseThrow(()->new UnauthorizedException("Account is inactive or unavailable"));return ResponseEntity.ok(issue(user));}catch(UnauthorizedException e){throw e;}catch(Exception e){throw new UnauthorizedException("Invalid or expired refresh token");}}
    private LoginResponse issue(User user){return new LoginResponse(jwtService.generateToken(user.getUserId(),user.getEmail(),user.getRole().name()),jwtService.generateRefreshToken(user.getUserId(),user.getEmail(),user.getRole().name()),user);}
}
